using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;

// Batched, original hard-surface geometry: one mesh per material, shared between city instances.
public sealed class FrontierArt : IDisposable {
 public readonly Material armor,porcelain,dark,glass,cyan,gold,violet,solar,star,beamCyan,beamViolet,beamOrange;
 readonly List<UnityEngine.Object> owned=new List<UnityEngine.Object>();readonly Dictionary<string,Mesh[]> cached=new Dictionary<string,Mesh[]>();
 static Mesh cube,cylinder,sphere,pressureHull;public static readonly Color[] Paints={new Color(.66f,.78f,.83f),new Color(.14f,.28f,.37f),new Color(.65f,.24f,.075f),new Color(.34f,.16f,.48f)};
 public FrontierArt(){armor=Material(new Color(.19f,.26f,.32f),.8f);porcelain=Material(new Color(.65f,.73f,.76f),.45f);dark=Material(new Color(.025f,.045f,.064f),.65f);glass=Material(new Color(.025f,.07f,.105f),.9f,1);cyan=Material(new Color(.08f,.35f,.42f),.65f,0,1.6f);gold=Material(new Color(.7f,.27f,.045f),.75f,0,.45f);violet=Material(new Color(.19f,.07f,.29f),.65f,0,1.5f);solar=Material(new Color(.035f,.095f,.17f),.85f);star=Own(new Material(Shader.Find("Orbit/FrontierStar")));beamCyan=Beam(new Color(.1f,1,1)*3);beamViolet=Beam(new Color(1,.08f,.45f)*4);beamOrange=Beam(new Color(1,.35f,.03f)*3);InitMeshes();}
 T Own<T>(T obj)where T:UnityEngine.Object{owned.Add(obj);return obj;}
 Material Beam(Color c){var m=Own(new Material(Shader.Find("Orbit/Glow")));m.SetColor("_Color",c);return m;}
 Material Material(Color c,float metal,float windows=0,float emission=0){var m=Own(new Material(Shader.Find("Orbit/FrontierArchitecture")));m.SetColor("_BaseColor",c);m.SetColor("_Accent",windows>0?new Color(.27f,.85f,1):c);m.SetFloat("_Metallic",metal);m.SetFloat("_Glass",windows);m.SetFloat("_Glow",emission);return m;}
 static void InitMeshes(){if(cube!=null)return;var vertices=new List<Vector3>();var triangles=new List<int>();float[] z={-.5f,-.30f,.20f,.5f},width={.28f,.5f,.35f,.025f},height={.26f,.5f,.25f,.025f};for(int r=0;r<4;r++)for(int j=0;j<8;j++){float a=j*Mathf.PI/4;vertices.Add(new Vector3(Mathf.Cos(a)*width[r],Mathf.Sin(a)*height[r],z[r]));}for(int r=0;r<3;r++)for(int j=0;j<8;j++){int a=r*8+j,b=r*8+(j+1)%8,c=(r+1)*8+j,d=(r+1)*8+(j+1)%8;triangles.AddRange(new[]{a,b,c,b,d,c});}pressureHull=new Mesh{name="Shared beveled pressure hull"};pressureHull.SetVertices(vertices);pressureHull.SetTriangles(triangles,0);pressureHull.RecalculateNormals();pressureHull.RecalculateBounds();var sample=GameObject.CreatePrimitive(PrimitiveType.Cube);cube=sample.GetComponent<MeshFilter>().sharedMesh;UnityEngine.Object.Destroy(sample);sample=GameObject.CreatePrimitive(PrimitiveType.Cylinder);cylinder=sample.GetComponent<MeshFilter>().sharedMesh;UnityEngine.Object.Destroy(sample);sample=GameObject.CreatePrimitive(PrimitiveType.Sphere);sphere=sample.GetComponent<MeshFilter>().sharedMesh;UnityEngine.Object.Destroy(sample);}
 public sealed class Batch {
  public readonly List<CombineInstance>[] parts=new List<CombineInstance>[8];public Batch(){for(int i=0;i<parts.Length;i++)parts[i]=new List<CombineInstance>();}
  public void Add(Mesh mesh,Vector3 p,Vector3 scale,int mat,Quaternion rotation=default(Quaternion)){if(rotation==default(Quaternion))rotation=Quaternion.identity;parts[mat].Add(new CombineInstance{mesh=mesh,transform=Matrix4x4.TRS(p,rotation,scale)});}
  public void Box(Vector3 p,Vector3 size,int mat,Quaternion rotation=default(Quaternion)){Add(cube,p,size,mat,rotation);}
  public void Cylinder(Vector3 p,float radius,float height,int mat,Quaternion rotation=default(Quaternion)){Add(cylinder,p,new Vector3(radius*2,height*.5f,radius*2),mat,rotation);}
  public void Orb(Vector3 p,Vector3 size,int mat){Add(sphere,p,size,mat);}
  public void Beam(Vector3 from,Vector3 to,float width,int mat){Box((from+to)*.5f,new Vector3(width,(to-from).magnitude,width),mat,Quaternion.FromToRotation(Vector3.up,to-from));}
  public void Ring(Vector3 center,float radius,float width,int mat,int segments=40){for(int i=0;i<segments;i++){float a=i*Mathf.PI*2/segments,b=(i+1)*Mathf.PI*2/segments;Beam(center+new Vector3(Mathf.Cos(a)*radius,0,Mathf.Sin(a)*radius),center+new Vector3(Mathf.Cos(b)*radius,0,Mathf.Sin(b)*radius),width,mat);}}
 }
 Material[] Materials{get{return new[]{armor,porcelain,dark,glass,cyan,gold,violet,solar};}}
 Mesh[] Compile(Batch b,string key){if(cached.TryGetValue(key,out var meshes))return meshes;meshes=new Mesh[8];for(int i=0;i<8;i++)if(b.parts[i].Count>0){var m=Own(new Mesh{name="Batched frontier / "+key+" / "+i,indexFormat=IndexFormat.UInt32});m.CombineMeshes(b.parts[i].ToArray(),true,true);m.RecalculateBounds();meshes[i]=m;}cached.Add(key,meshes);return meshes;}
 public Transform Render(Transform parent,Mesh[] meshes,string name,int layer=0,Material paint=null){var root=new GameObject(name).transform;root.SetParent(parent,false);root.gameObject.layer=layer;var materials=Materials;for(int i=0;i<meshes.Length;i++)if(meshes[i]!=null){var g=new GameObject("Combined surface "+i);g.layer=layer;g.transform.SetParent(root,false);g.AddComponent<MeshFilter>().sharedMesh=meshes[i];var r=g.AddComponent<MeshRenderer>();r.sharedMaterial=i==1&&paint!=null?paint:materials[i];r.shadowCastingMode=ShadowCastingMode.On;}return root;}
 public Material Coating(int palette){return Material(Paints[Mathf.Clamp(palette,0,3)],.7f);}
 public float Radius(int kind){return kind==0?14:kind==1?24:kind==2?19:kind==3?24:kind==4?18:kind==5?25:kind==6?29:16;}
 public Transform District(Transform parent,int kind,int layer=0){string key="district"+kind;if(cached.TryGetValue(key,out var old))return Render(parent,old,CivilizationModel.DistrictNames[kind],layer);var b=new Batch();float radius=Radius(kind);b.Cylinder(new Vector3(0,-12,0),radius,24,0,default(Quaternion));b.Ring(new Vector3(0,.06f,0),radius-.5f,.15f,4);for(int k=0;k<4;k++){float a=k*Mathf.PI*.5f;b.Box(new Vector3(Mathf.Cos(a)*(radius-1),.1f,Mathf.Sin(a)*(radius-1)),new Vector3(2,.15f,2),5);}
  if(kind==0){for(int j=0;j<5;j++){float h=6-j*.65f,w=11-j*1.5f;float y=1+j*6;b.Box(new Vector3(0,y+h*.5f,0),new Vector3(w,h,w*.72f),j%2==0?3:1);b.Box(new Vector3(0,y+h,0),new Vector3(w+1,.45f,w*.72f+1),0);}b.Cylinder(new Vector3(0,33,0),.5f,9,0);b.Ring(new Vector3(0,31,0),4,.35f,4);for(int side=-1;side<=1;side+=2)b.Box(new Vector3(side*7,10,0),new Vector3(1.3f,20,7),1);}
  else if(kind==1){for(int i=0;i<6;i++){float a=i*Mathf.PI/3,h=13+(i*7%20);Vector3 p=new Vector3(Mathf.Cos(a)*13,h*.5f,Mathf.Sin(a)*13);b.Box(p,new Vector3(7,h,7),3);b.Box(new Vector3(p.x,h+.4f,p.z),new Vector3(8,.8f,8),1);for(int j=4;j<h;j+=6)b.Box(new Vector3(p.x,j,p.z),new Vector3(7.5f,.35f,7.5f),0);}b.Cylinder(new Vector3(0,.2f,0),4,.5f,1);b.Orb(new Vector3(0,3,0),new Vector3(3,4,3),4);}
  else if(kind==2){for(int i=0;i<3;i++){b.Cylinder(new Vector3(-10+i*10,6,0),3.5f,12,0);b.Ring(new Vector3(-10+i*10,4,0),3.6f,.25f,5);b.Cylinder(new Vector3(-10+i*10,13,0),1,2,5);}for(int side=-1;side<=1;side+=2){b.Box(new Vector3(0,2,side*11),new Vector3(27,3,3),2);b.Box(new Vector3(0,3.6f,side*11),new Vector3(25,.25f,1),5);}b.Beam(new Vector3(-13,0,-11),new Vector3(-13,22,-11),1,0);b.Beam(new Vector3(-13,22,-11),new Vector3(11,22,-11),1,5);b.Beam(new Vector3(10,22,-11),new Vector3(10,9,-11),.2f,0);}
  else if(kind==3){for(int row=-1;row<=1;row+=2)for(int i=0;i<5;i++){Vector3 p=new Vector3(-16+i*8,3,row*10);b.Cylinder(p-Vector3.up, .35f,4,0);b.Box(p,new Vector3(6.8f,.28f,12),7,Quaternion.Euler(row*18,0,0));for(int j=0;j<6;j++)b.Box(p+new Vector3(-2.8f+j*1.1f,.2f,0),new Vector3(.045f,.08f,11),4,Quaternion.Euler(row*18,0,0));}b.Box(new Vector3(0,1,0),new Vector3(8,2,5),0);}
  else if(kind==4){b.Cylinder(new Vector3(0,1,0),13,2,1);b.Orb(new Vector3(0,1.5f,0),new Vector3(22,16,22),3);for(int i=0;i<4;i++)b.Ring(new Vector3(0,2+i*2,0),12-i*.7f,.22f,0);b.Cylinder(new Vector3(12,10,6),1,20,0);b.Orb(new Vector3(12,20,6),new Vector3(5,1.4f,5),4);b.Beam(new Vector3(-12,1,0),new Vector3(-12,12,0),.45f,5);}
  else if(kind==5){b.Cylinder(new Vector3(0,.2f,0),16,.4f,2);b.Ring(new Vector3(0,.5f,0),13,.3f,5);b.Ring(new Vector3(0,.55f,0),7,.2f,4);for(int i=-1;i<=1;i+=2){b.Box(new Vector3(i*19,13,-12),new Vector3(2,26,3),0);b.Beam(new Vector3(i*19,25,-12),new Vector3(i*5,25,-12),1,5);for(int j=2;j<26;j+=4)b.Box(new Vector3(i*19,j,-12),new Vector3(2.4f,.3f,3.4f),1);}b.Box(new Vector3(0,6,-19),new Vector3(18,10,6),3);}
  else if(kind==6){for(int s=-1;s<=1;s+=2){b.Box(new Vector3(s*20,16,0),new Vector3(5,32,10),0);b.Box(new Vector3(s*20,30,0),new Vector3(7,5,12),3);b.Beam(new Vector3(s*20,32,-8),new Vector3(-s*20,32,8),1.2f,5);for(int j=0;j<5;j++)b.Box(new Vector3(s*20,3+j*5,5.5f),new Vector3(5,.3f,.3f),4);}b.Box(new Vector3(0,33,0),new Vector3(45,2.5f,11),1);b.Box(new Vector3(0,2,0),new Vector3(15,2,29),2);b.Ring(new Vector3(0,5,0),10,.5f,4);}
  else{b.Cylinder(new Vector3(0,2,0),10,4,0);b.Orb(new Vector3(0,8,0),new Vector3(9,9,9),4);b.Ring(new Vector3(0,8,0),8,.5f,1);for(int i=0;i<3;i++){float a=i*Mathf.PI*2/3;Vector3 p=new Vector3(Mathf.Cos(a)*11,4,Mathf.Sin(a)*11);b.Cylinder(p,2.5f,8,0);b.Beam(p+Vector3.up*4,p+new Vector3(Mathf.Cos(a)*5,9,Mathf.Sin(a)*5),1,1);}}
  for(int i=0;i<6;i++){float a=i*Mathf.PI/3;Vector3 p=new Vector3(Mathf.Cos(a)*(radius-2),2,Mathf.Sin(a)*(radius-2));b.Cylinder(p,.14f,4,0);b.Orb(p+Vector3.up*2,Vector3.one*.6f,4);}return Render(parent,Compile(b,key),CivilizationModel.DistrictNames[kind],layer);
 }
 public Transform Hull(Transform parent,int type,Material coating=null,int layer=0){string key="hull"+type;if(cached.TryGetValue(key,out var old))return Render(parent,old,CivilizationModel.HullNames[type],layer,coating);var b=new Batch();float length=type==3?5.8f:type==1?4.8f:4.1f,width=type==3?1.15f:.75f;
  b.Box(new Vector3(0,0,-.3f),new Vector3(width*1.5f,.55f,length*.7f),0);b.Add(pressureHull,new Vector3(0,.12f,length*.12f),new Vector3(width*1.9f,1.0f,length*.92f),1);b.Box(new Vector3(0,.47f,length*.1f),new Vector3(.65f,.24f,.95f),3);b.Box(new Vector3(0,.36f,-.8f),new Vector3(.75f,.18f,1.2f),1);
  for(int side=-1;side<=1;side+=2){Vector3 p=new Vector3(side*(type==3?1.65f:1.05f),-.06f,-.75f);float sweep=type==2?38:22;b.Box(p,new Vector3(type==3?2.2f:1.6f,.12f,type==1?1.65f:1.0f),0,Quaternion.Euler(0,side*sweep,-side*6));b.Box(p+new Vector3(0,.08f,.1f),new Vector3(type==3?1.6f:1.2f,.05f,.38f),1,Quaternion.Euler(0,side*sweep,0));b.Cylinder(new Vector3(side*width,-.1f,-length*.34f),.27f,1.4f,2,Quaternion.Euler(90,0,0));b.Cylinder(new Vector3(side*width,-.1f,-length*.5f),.30f,.18f,5,Quaternion.Euler(90,0,0));b.Cylinder(new Vector3(side*width,-.1f,-length*.53f),.21f,.06f,4,Quaternion.Euler(90,0,0));b.Box(new Vector3(side*.48f,.24f,.25f),new Vector3(.045f,.045f,.8f),4);for(int j=0;j<5;j++)b.Box(new Vector3(side*.42f,.33f,-1.3f+j*.17f),new Vector3(.2f,.04f,.06f),2);
   if(type==1){b.Box(new Vector3(side*1.1f,-.25f,.4f),new Vector3(.7f,.55f,1.6f),1);for(int j=0;j<3;j++)b.Box(new Vector3(side*1.12f,.05f,-.1f+j*.45f),new Vector3(.72f,.045f,.1f),5);}
   if(type>=2){for(int j=0;j<(type==3?3:2);j++){b.Cylinder(new Vector3(side*(1.15f+j*.23f),.1f,.5f-j*.15f),.075f,.95f,2,Quaternion.Euler(90,0,0));b.Orb(new Vector3(side*(1.15f+j*.23f),.1f,1-j*.15f),Vector3.one*.13f,4);}b.Box(new Vector3(side*1.4f,.3f,-1.0f),new Vector3(.12f,.75f,.65f),1,Quaternion.Euler(-22,0,side*10));}
  }
  if(type==0){b.Beam(new Vector3(0,.45f,-1),new Vector3(0,1.15f,-1),.055f,0);b.Orb(new Vector3(0,1.15f,-1),new Vector3(.4f,.08f,.4f),4);}if(type==3){b.Box(new Vector3(0,.8f,-1.2f),new Vector3(.75f,.85f,.7f),0);b.Box(new Vector3(0,1.25f,-1.05f),new Vector3(1.05f,.22f,.6f),3);b.Box(new Vector3(0,-.5f,-.45f),new Vector3(1.0f,.35f,2.7f),1);}
  HullDetail(b,type,length,width);
  return Render(parent,Compile(b,key),CivilizationModel.HullNames[type],layer,coating);
 }
 public void HullDetail(Batch b,int type,float length,float width){
  // Shared, batched plates, intake shrouds, cooling vanes and structural spars.
  for(int side=-1;side<=1;side+=2){
   for(int i=0;i<8;i++){float z=-length*.33f+i*length*.067f;float span=width*(.48f+.10f*Mathf.Sin(i*.6f));b.Add(pressureHull,new Vector3(side*span,.23f,z),new Vector3(width*.7f,.18f,length*.14f),1,Quaternion.Euler(0,side*7,0));b.Box(new Vector3(side*span,.35f,z),new Vector3(width*.46f,.025f,.025f),2);}
   for(int i=0;i<9;i++){float z=-length*.43f+i*.065f;b.Box(new Vector3(side*width,-.09f,z),new Vector3(.47f,.038f,.025f),5,Quaternion.Euler(0,0,side*23));}
   b.Add(pressureHull,new Vector3(side*(width+.27f),-.08f,-length*.18f),new Vector3(.5f,.54f,1.8f),0);
   b.Beam(new Vector3(side*.36f,.2f,length*.37f),new Vector3(side*(width+.5f),.12f,-length*.25f),.045f,5);
   b.Box(new Vector3(side*(width+.8f),.04f,-.86f),new Vector3(.075f,.07f,.45f),4);
   for(int j=0;j<4;j++)b.Box(new Vector3(side*(width+.45f),.08f,-1.25f+j*.18f),new Vector3(.35f,.05f,.04f),2);
   if(type>=2){b.Add(pressureHull,new Vector3(side*(width+.4f),.32f,-.2f),new Vector3(.5f,.4f,1.2f),1);b.Cylinder(new Vector3(side*(width+.4f),.34f,.45f),.09f,.45f,5,Quaternion.Euler(90,0,0));}
  }
  b.Box(new Vector3(0,.495f,length*.10f),new Vector3(.025f,.018f,.95f),0);
  b.Box(new Vector3(0,.50f,length*.10f),new Vector3(.65f,.025f,.025f),0);
  for(int i=0;i<5;i++)b.Box(new Vector3(0,-.31f,-length*.28f+i*.24f),new Vector3(width*.72f,.035f,.055f),2);
 }
 public Transform Rocket(Transform parent,int layer=0){string key="rocket";if(cached.TryGetValue(key,out var old))return Render(parent,old,"AURORA / survey rocket",layer);var b=new Batch();b.Cylinder(new Vector3(0,7,0),1.35f,11,1);b.Cylinder(new Vector3(0,9,0),1.4f,.55f,2);b.Cylinder(new Vector3(0,2.4f,0),1.42f,.7f,5);b.Orb(new Vector3(0,12.4f,0),new Vector3(2.6f,5.0f,2.6f),1);b.Cylinder(new Vector3(0,12.2f,0),1.4f,.35f,4);for(int s=-1;s<=1;s+=2){b.Cylinder(new Vector3(s*2,4,0),.65f,6,1);b.Orb(new Vector3(s*2,7,0),new Vector3(1.25f,1.8f,1.25f),5);b.Box(new Vector3(s*1.8f,2,0),new Vector3(2,.12f,2.5f),0,Quaternion.Euler(0,0,s*40));b.Cylinder(new Vector3(s*2,.6f,0),.68f,.3f,2);}b.Cylinder(new Vector3(0,1,0),.9f,1.3f,2);return Render(parent,Compile(b,key),"AURORA / survey rocket",layer);}
 public Transform Collector(Transform parent,int sector,int count,float radius,int layer=0){var root=new GameObject("Dyson collector sector "+sector).transform;root.SetParent(parent,false);var b=new Batch();for(int row=0;row<7;row++)for(int col=0;col<8;col++){float latitude=Mathf.Lerp(-1.10f,1.10f,(row+.5f)/7),angle=(sector+(col+.5f)/8f)*Mathf.PI*2/12;Vector3 normal=new Vector3(Mathf.Cos(latitude)*Mathf.Cos(angle),Mathf.Sin(latitude),Mathf.Cos(latitude)*Mathf.Sin(angle));Quaternion q=Quaternion.LookRotation(normal,Vector3.up);Vector3 p=normal*radius;float w=radius*.040f,h=radius*.10f;b.Box(p,new Vector3(w,h,radius*.0018f),7,q);b.Box(p+normal*radius*.002f,new Vector3(w*.92f,h*.90f,radius*.001f),4,q);}string key="collector"+sector+"r"+radius;return Render(root,Compile(b,key),"56 autonomous stellar collectors",layer);}
 public Transform AlienCity(Transform parent,int race){string key="alien-city"+race;if(cached.TryGetValue(key,out var old))return Render(parent,old,"Alien arcology",0);var b=new Batch();b.Cylinder(new Vector3(0,-1,0),54,2,2);b.Ring(new Vector3(0,.05f,0),51,.5f,race==2?6:4);for(int i=0;i<9;i++){float a=i*Mathf.PI*2/9,r=i==0?0:26;Vector3 p=new Vector3(Mathf.Cos(a)*r,0,Mathf.Sin(a)*r);float h=25+(i*17%30);b.Add(pressureHull,p+Vector3.up*h*.5f,new Vector3(9,12,h),race==2?6:3,Quaternion.Euler(-90,i*37,0));b.Ring(p+Vector3.up*4,6,.3f,5);if(i%2==0)b.Orb(p+Vector3.up*(h+1),Vector3.one*3,race==2?5:4);}return Render(parent,Compile(b,key),"Alien arcology / "+race,0);}
 public void Dispose(){foreach(var o in owned)if(o!=null)UnityEngine.Object.Destroy(o);owned.Clear();cached.Clear();}
}
